function isImageContentType(contentType: string, fileName?: string): boolean {
  const t = (contentType || '').toLowerCase();
  if (/^image\/(jpeg|png|webp)$/.test(t)) return true;
  return /\.(jpe?g|png|webp)$/i.test(fileName || '');
}

function isVideoContentType(contentType: string, fileName?: string): boolean {
  const t = (contentType || '').toLowerCase();
  if (/^video\/(mp4|webm)$/.test(t)) return true;
  return /\.(mp4|webm)$/i.test(fileName || '');
}

/** Wrap FileService client — image ≤10MB · video ≤50MB (BE count only). */
export function createPatrolMediaUploadApi(): LinImageUploadApi {
  const base = createDefaultLinImageUploadApi();
  return {
    ...base,
    init: async (body) => {
      const img = isImageContentType(body.contentType, body.fileName);
      const vid = isVideoContentType(body.contentType, body.fileName);
      if (!img && !vid) {
        throw new Error('Định dạng không hỗ trợ (jpeg/png/webp/mp4/webm).');
      }
      if (img && body.sizeBytes > PATROL_IMAGE_MAX_BYTES) {
        const err = new Error('FILE_TOO_LARGE') as Error & { errorCode?: string; status?: number };
        err.errorCode = 'FILE_TOO_LARGE';
        err.status = 413;
        throw err;
      }
      if (vid && body.sizeBytes > PATROL_VIDEO_MAX_BYTES) {
        const err = new Error('FILE_TOO_LARGE') as Error & { errorCode?: string; status?: number };
        err.errorCode = 'FILE_TOO_LARGE';
        err.status = 413;
        throw err;
      }
      return base.init(body);
    },
  };
}

/** Persist guids only — staged uploadId or committed attachmentId. */
export function mediaIdsFromUploadItems(items: LinImageUploadItem[]): string[] {
  const ids: string[] = [];
  for (const item of items) {
    if (item.status === 'error' || item.status === 'uploading' || item.status === 'pending') {
      continue;
    }
    const id = (item.attachmentId || item.uploadId || '').trim();
    if (!id) continue;
    if (!ids.includes(id)) ids.push(id);
    if (ids.length >= PATROL_MEDIA_MAX) break;
  }
  return ids;
}

export function uploadItemsFromMediaIds(ids: string[] | undefined | null): LinImageUploadItem[] {
  if (!ids?.length) return [];
  return ids.slice(0, PATROL_MEDIA_MAX).map((id, index) => ({
    localId: `committed-${id}`,
    fileName: `media-${index + 1}`,
    displayName: `Tệp ${index + 1}`,
    sizeBytes: 0,
    contentType: '',
    attachmentId: id,
    status: 'committed' as const,
  }));
}
