import React, { useEffect, useMemo, useState } from 'react';
import { useLocation, useParams, useSearchParams } from 'react-router-dom';
import { useShellPageTitle } from '../../router/useShellPageTitle';
import {
  Button,
  Input,
  LinImageUpload,
  LinPageHeader,
  SearchInput,
  useAppToast,
  type LinImageUploadItem,
} from '@linm-soft-org/linm-web-common-components';
import { GiaoViecModal, type GiaoViecContextPatrol } from '../../components/GiaoViecModal';
import { TaskChatPanel, type TaskChatTarget } from '../../components/TaskChatPanel/TaskChatPanel';
import { useInAppNavigate } from '../../router/navigateInAppPath';
import {
  isPlatformTaskIntegrationReady,
  platformTaskPrereqTooltip,
} from '../../utils/platformTaskPrereq';
import { patrolSessionPrefill } from '../../utils/taskPriorityPrefill';
import { patrolService } from '../../services/patrol/patrolService';
import { patrolListPermissions } from '../../services/patrol/permissions';
import type { PatrolDto } from '../../services/patrol/responseModel';
import {
  createPatrolMediaUploadApi,
  mediaIdsFromUploadItems,
  PATROL_MEDIA_ACCEPT,
  PATROL_MEDIA_LABELS,
  PATROL_MEDIA_MAX,
  PATROL_VIDEO_MAX_BYTES,
  uploadItemsFromMediaIds,
} from '../../services/patrol/mediaUpload';
import {
  OFFLINE_LOOKUP,
  OFFLINE_LOOKUP_CONFIG,
  STATUS_LOOKUP,
  STATUS_LOOKUP_CONFIG,
  TYPE_LOOKUP,
  TYPE_LOOKUP_CONFIG,
  lookupLabel,
  lookupRoadRouteLabel,
  ROAD_ROUTE_SEED,
} from '../../services/patrol/lookups';
import { RmmsOrgFormFields } from '../../filters/RmmsOrgFormFields';
import {
  orgFromDto,
  orgPersistPayload,
  type RmmsOrgFormValue,
} from '../../filters/rmmsOrgForm';
import {
  EMPTY_FORM,
  genCode,
  loadRows,
  type PatrolRow,
} from '../../demo/patrolStore';
import { buildRmmsDetailToolbar, rmmsFormActionButton } from '../buildRmmsGenericToolbar';
import styles from './PatrolFormPage.module.css';

export type PatrolFormMode = 'create' | 'edit' | 'view' | 'copy';

type FormState = Omit<PatrolRow, 'id'> & { userDisplayName?: string };

const REQUIRED: (keyof FormState)[] = [
  'userName',
  'route',
  'patrolType',
  'plannedDate',
  'checkInCount',
  'status',
];

function orgOf(form: FormState): RmmsOrgFormValue {
  return {
    zoneOrgCode: form.zoneOrgCode ?? '',
    zoneOrgName: form.zoneOrgName ?? '',
    vpOrgCode: form.vpOrgCode ?? '',
    vpOrgName: form.vpOrgName ?? '',
    assigneeCode: form.assigneeCode ?? '',
    assigneeName: form.assigneeOrgName ?? '',
    routeCode: form.routeCode || form.route || '',
    routeName: '',
  };
}
const TEST_ID = 'rmms-patrol-form';
const PAGE_ID = 'patrol-form';

const MODE_TITLE: Record<PatrolFormMode, string> = {
  create: 'Tạo mới phiên tuần',
  edit: 'Sửa phiên tuần',
  view: 'Xem phiên tuần',
  copy: 'Sao chép phiên tuần',
};

function toLocalInput(iso: string): string {
  if (!iso) return '';
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '';
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function fromLocalInput(local: string): string {
  if (!local) return '';
  const d = new Date(local);
  return Number.isNaN(d.getTime()) ? '' : d.toISOString();
}

function fromDto(dto: PatrolDto, asCopy: boolean): FormState {
  const mediaIds = [...(dto.mediaIds ?? [])].slice(0, PATROL_MEDIA_MAX);
  return {
    code: asCopy ? genCode(loadRows()) : dto.code,
    userName: dto.userName,
    userDisplayName: dto.userDisplayName?.trim() || '',
    route: dto.route,
    ...orgFromDto({ ...dto, route: dto.route }),
    assigneeOrgName: dto.assigneeOrgName ?? '',
    patrolType: dto.patrolType,
    plannedDate: (dto.plannedDate || '').slice(0, 10),
    startedAt: dto.startedAt ?? '',
    checkInCount: dto.checkInCount,
    coveragePercent: dto.coveragePercent,
    status: dto.status,
    offlineQueued: dto.offlineQueued,
    note: dto.note ?? '',
    mediaIds,
    updatedAt: dto.updatedAt ?? '',
    isActive: dto.isActive !== false,
  };
}

function formatDate(iso: string): string {
  if (!iso) return '—';
  try {
    const d = new Date(iso.length === 10 ? `${iso}T00:00:00` : iso);
    return d.toLocaleString('vi-VN');
  } catch {
    return iso;
  }
}

const CREATE_SLUGS = new Set(['new', 'tao-moi']);

const PatrolFormPage: React.FC = () => {
  const { id } = useParams();
  const { pathname } = useLocation();
  const [searchParams] = useSearchParams();
  const navigate = useInAppNavigate();
  const perms = patrolListPermissions();
  const copyFrom = searchParams.get('copyFrom');
  const modeParam = searchParams.get('mode');

  const mode: PatrolFormMode = useMemo(() => {
    const isCreatePath =
      pathname.endsWith('/tao-moi') || !id || CREATE_SLUGS.has(id);
    if (isCreatePath) return copyFrom ? 'copy' : 'create';
    if (modeParam === 'edit') return 'edit';
    if (modeParam === 'copy') return 'copy';
    return 'view';
  }, [id, copyFrom, modeParam, pathname]);

  const isView = mode === 'view';
  const [form, setForm] = useState<FormState>({ ...EMPTY_FORM });
  const [currentId, setCurrentId] = useState<string | null>(null);
  const [invalid, setInvalid] = useState<Set<string>>(new Set());
  const [showBanner, setShowBanner] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [giaoViecOpen, setGiaoViecOpen] = useState(false);
  const [giaoViecContext, setGiaoViecContext] = useState<GiaoViecContextPatrol | null>(null);
  const [chatTarget, setChatTarget] = useState<TaskChatTarget | null>(null);
  const toast = useAppToast();
  const platformReady = isPlatformTaskIntegrationReady();
  const [mediaItems, setMediaItems] = useState<LinImageUploadItem[]>([]);
  const mediaApi = useMemo(() => createPatrolMediaUploadApi(), []);

  useEffect(() => {
    let cancelled = false;
    const boot = async () => {
      setLoading(true);
      setInvalid(new Set());
      setShowBanner(false);
      setDirty(false);
      try {
        if (mode === 'create') {
          setCurrentId(null);
          setForm({
            ...EMPTY_FORM,
            code: '(tự sinh)',
            plannedDate: new Date().toISOString().slice(0, 10),
            startedAt: new Date().toISOString(),
            updatedAt: '',
            mediaIds: [],
          });
          setMediaItems([]);
          return;
        }
        const sourceId = mode === 'copy' ? copyFrom ?? id : id;
        if (!sourceId) {
          navigate('/td-tk');
          return;
        }
        const dto = await patrolService.getById(sourceId);
        if (cancelled) return;
        setCurrentId(mode === 'copy' ? null : dto.id);
        const next = fromDto(dto, mode === 'copy');
        setForm(next);
        // Copy clones guid[] (share FileService refs · no re-upload).
        setMediaItems(uploadItemsFromMediaIds(next.mediaIds));
      } catch {
        if (!cancelled) navigate('/td-tk');
      } finally {
        if (!cancelled) setLoading(false);
      }
    };
    void boot();
    return () => {
      cancelled = true;
    };
  }, [mode, id, copyFrom, navigate]);

  const onMediaChange = (items: LinImageUploadItem[]) => {
    if (isView) return;
    setDirty(true);
    setMediaItems(items);
    setForm((prev) => ({ ...prev, mediaIds: mediaIdsFromUploadItems(items) }));
  };

  const updateField = <K extends keyof FormState>(key: K, value: FormState[K]) => {
    if (isView) return;
    setDirty(true);
    setForm((prev) => ({ ...prev, [key]: value }));
    setInvalid((prev) => {
      const next = new Set(prev);
      next.delete(String(key));
      return next;
    });
  };

  const goList = () => {
    if (!isView && dirty) {
      const ok = window.confirm('Bạn có thay đổi chưa lưu. Thoát mà không lưu?');
      if (!ok) return;
    }
    navigate('/td-tk');
  };

  const validate = (snapshot: FormState): boolean => {
    const bad = new Set<string>();
    REQUIRED.forEach((key) => {
      const val = snapshot[key];
      if (val === '' || val == null || (typeof val === 'string' && !val.trim())) {
        bad.add(key);
      }
    });
    if (Number.isNaN(Number(snapshot.checkInCount)) || snapshot.checkInCount < 0) {
      bad.add('checkInCount');
    }
    if (
      Number.isNaN(Number(snapshot.coveragePercent)) ||
      snapshot.coveragePercent < 0 ||
      snapshot.coveragePercent > 100
    ) {
      bad.add('coveragePercent');
    }
    setInvalid(bad);
    setShowBanner(bad.size > 0);
    return bad.size === 0;
  };

  const handleSave = async () => {
    if (isView) return;
    if (mode === 'edit' && !perms.canUpdate) return;
    if ((mode === 'create' || mode === 'copy') && !perms.canCreate) return;
    if (!validate(form)) return;
    setSaving(true);
    try {
      const mediaIds = mediaIdsFromUploadItems(mediaItems);
      const payload = {
        userName: form.userName.trim(),
        route: (form.routeCode || form.route).trim(),
        ...orgPersistPayload(orgOf(form)),
        patrolType: form.patrolType,
        plannedDate: form.plannedDate,
        startedAt: form.startedAt || null,
        checkInCount: Number(form.checkInCount),
        coveragePercent: Number(form.coveragePercent),
        status: form.status,
        offlineQueued: form.offlineQueued,
        note: form.note,
        mediaIds,
      };
      if (mode === 'edit' && currentId) {
        await patrolService.update(currentId, payload);
      } else {
        await patrolService.create(payload);
      }
      setDirty(false);
      navigate('/td-tk');
    } finally {
      setSaving(false);
    }
  };

  const fieldClass = (key: string) =>
    [styles.field, invalid.has(key) ? styles.fieldInvalid : ''].filter(Boolean).join(' ');

  const toolbar = buildRmmsDetailToolbar({
    testIdPrefix: TEST_ID,
    onBack: goList,
    right: (
      <>
        {isView && currentId && perms.canUpdate
          ? rmmsFormActionButton({
              testId: `${TEST_ID}-btn-to-edit`,
              label: 'Sửa',
              icon: 'fas fa-pen',
              onClick: () => navigate(`/td-tk/${encodeURIComponent(currentId)}?mode=edit`),
            })
          : null}
        {isView && currentId && perms.canCreate
          ? rmmsFormActionButton({
              testId: `${TEST_ID}-btn-to-copy`,
              label: 'Sao chép',
              icon: 'fas fa-copy',
              onClick: () =>
                navigate(`/td-tk/tao-moi?copyFrom=${encodeURIComponent(currentId)}`),
            })
          : null}
        {!isView
          ? rmmsFormActionButton({
              testId: `${TEST_ID}-btn-cancel`,
              label: 'Hủy',
              icon: 'fas fa-times',
              onClick: goList,
            })
          : null}
        {!isView
          ? rmmsFormActionButton({
              testId: `${TEST_ID}-btn-save`,
              label: 'Lưu',
              icon: 'fas fa-save',
              variant: 'primary',
              onClick: () => void handleSave(),
              loading: saving,
            })
          : null}
      </>
    ),
  });

  const openGiaoViec = () => {
    if (!platformReady) return;
    if (!currentId) return;
    const routeLabel =
      lookupRoadRouteLabel(ROAD_ROUTE_SEED, form.route) || form.route || 'Tuần tra';
    const prefill = patrolSessionPrefill(routeLabel);
    setGiaoViecContext({
      source: 'patrol',
      sourceEntityType: 'patrol_session',
      sourceEntityId: currentId,
      sessionCode: form.code,
      route: routeLabel,
      title: prefill.title,
      description: form.note ? `Từ phiên tuần tra: ${form.note}` : 'Từ kết ca tuần đường',
      priority: prefill.priority,
      assignmentStrategy: 'pool',
      dueDate: prefill.dueDate,
    });
    setGiaoViecOpen(true);
  };

  const viewBody = (
    <>
      <div className={styles.contextStrip} data-des-id="DES-RTI-PATROL-FOOTER">
        <span>
          <strong>Mã ca:</strong> {form.code || '—'}
        </span>
        <span>
          <strong>Tuyến:</strong>{' '}
          {lookupRoadRouteLabel(ROAD_ROUTE_SEED, form.route) || form.route || '—'}
        </span>
      </div>
    <dl className={styles.viewGrid} data-form-cols="5" data-testid={`${TEST_ID}-view`}>
      <div>
        <dt>Mã phiên tuần</dt>
        <dd>{form.code || '—'}</dd>
      </div>
      <div>
        <dt>Trạng thái</dt>
        <dd>{lookupLabel(STATUS_LOOKUP, form.status)}</dd>
      </div>
      <div className={styles.span2}>
        <dt>Nhân viên</dt>
        <dd>{form.userDisplayName?.trim() || form.userName || '—'}</dd>
      </div>
      <div>
        <dt>Tuyến đường</dt>
        <dd>{lookupRoadRouteLabel(ROAD_ROUTE_SEED, form.route) || form.route || '—'}</dd>
      </div>
      <div>
        <dt>Loại tuần</dt>
        <dd>{lookupLabel(TYPE_LOOKUP, form.patrolType)}</dd>
      </div>
      <div>
        <dt>Ngày kế hoạch</dt>
        <dd>{form.plannedDate ? formatDate(form.plannedDate) : '—'}</dd>
      </div>
      <div>
        <dt>Bắt đầu thực tế</dt>
        <dd>{form.startedAt ? formatDate(form.startedAt) : '—'}</dd>
      </div>
      <div>
        <dt>Số điểm check-in</dt>
        <dd>{form.checkInCount}</dd>
      </div>
      <div>
        <dt>Coverage %</dt>
        <dd>{Number(form.coveragePercent).toFixed(1)}%</dd>
      </div>
      <div>
        <dt>Hàng đợi offline</dt>
        <dd>{form.offlineQueued ? 'Offline queue' : 'Online'}</dd>
      </div>
      <div className={styles.span2}>
        <dt>Ghi chú</dt>
        <dd>{form.note || '—'}</dd>
      </div>
    </dl>
      <section
        className={styles.mediaGallery}
        data-zone="media-gallery"
        data-testid={`${TEST_ID}-media-gallery`}
      >
        <h3 className={styles.sectionTitle}>Ảnh / video hiện trường</h3>
        {mediaItems.length === 0 ? (
          <p className={styles.mediaEmpty} data-testid={`${TEST_ID}-media-empty`}>
            Chưa có tệp đính kèm.
          </p>
        ) : (
          <LinImageUpload
            purpose="patrol-session-media"
            product="rmms"
            entityType="patrol_session"
            entityId={currentId ?? undefined}
            items={mediaItems}
            onChange={() => undefined}
            maxFiles={PATROL_MEDIA_MAX}
            maxBytes={PATROL_VIDEO_MAX_BYTES}
            accept={PATROL_MEDIA_ACCEPT}
            disabled
            allowRename={false}
            labels={PATROL_MEDIA_LABELS}
            client={mediaApi}
            testId={`${TEST_ID}-media-view`}
          />
        )}
      </section>
      <div className={styles.patrolFooter} data-des-id="DES-RTI-PATROL-FOOTER">
        <Button
          variant="primary"
          onClick={() => toast.info('«Kết ca» giữ nguyên flow supervise — không gộp create task.')}
          data-testid={`${TEST_ID}-btn-ket-ca`}
        >
          <i className="fas fa-flag-checkered" /> Kết ca
        </Button>
        <Button
          variant="secondary"
          disabled={!platformReady}
          title={platformReady ? undefined : platformTaskPrereqTooltip()}
          onClick={openGiaoViec}
          data-testid={`${TEST_ID}-btn-giao-viec`}
          data-des-id="DES-RTI-PREREQ"
        >
          <i className="fas fa-tasks" /> Giao việc
        </Button>
      </div>
    </>
  );

  const editBody = (
    <div className={styles.z2} data-form-cols="5" data-testid={`${TEST_ID}-z2`}>
      <section>
        <h3 className={styles.sectionTitle}>Thông tin phiên tuần</h3>
        <div className={styles.fields} data-form-cols="5">
          <div className={fieldClass('code')}>
            <Input
              label="Mã phiên tuần"
              value={form.code}
              disabled
              fullWidth
              data-testid={`${TEST_ID}-field-code`}
            />
          </div>
          <div className={fieldClass('status')} data-testid={`${TEST_ID}-field-status`}>
            <SearchInput
              label="Trạng thái"
              required
              config={STATUS_LOOKUP_CONFIG}
              value={form.status}
              primaryDisplay={lookupLabel(STATUS_LOOKUP, form.status)}
              showSecondaryInput={false}
              onChange={(item) => updateField('status', item.value)}
              onClear={() => updateField('status', '')}
              error={invalid.has('status') ? 'Bắt buộc' : undefined}
            />
          </div>
          <div className={`${fieldClass('userName')} ${styles.span2}`}>
            <Input
              label="Nhân viên"
              required
              value={form.userName}
              onChange={(e) => updateField('userName', e.target.value)}
              fullWidth
              error={invalid.has('userName') ? 'Bắt buộc' : undefined}
              data-testid={`${TEST_ID}-field-userName`}
            />
          </div>
          <RmmsOrgFormFields
            testIdPrefix={TEST_ID}
            value={orgOf(form)}
            disabled={isView}
            routeError={invalid.has('route') ? 'Bắt buộc' : undefined}
            onChange={(next) => {
              setForm((f) => ({
                ...f,
                zoneOrgCode: next.zoneOrgCode,
                zoneOrgName: next.zoneOrgName,
                vpOrgCode: next.vpOrgCode,
                vpOrgName: next.vpOrgName,
                assigneeCode: next.assigneeCode,
                assigneeOrgName: next.assigneeName,
                routeCode: next.routeCode,
                route: next.routeCode,
              }));
              setDirty(true);
            }}
          />
          <div className={fieldClass('patrolType')} data-testid={`${TEST_ID}-field-patrolType`}>
            <SearchInput
              label="Loại tuần"
              required
              config={TYPE_LOOKUP_CONFIG}
              value={form.patrolType}
              primaryDisplay={lookupLabel(TYPE_LOOKUP, form.patrolType)}
              showSecondaryInput={false}
              onChange={(item) => updateField('patrolType', item.value)}
              onClear={() => updateField('patrolType', '')}
              error={invalid.has('patrolType') ? 'Bắt buộc' : undefined}
            />
          </div>
          <div className={fieldClass('plannedDate')}>
            <Input
              label="Ngày kế hoạch"
              required
              type="date"
              value={form.plannedDate}
              onChange={(e) => updateField('plannedDate', e.target.value)}
              fullWidth
              error={invalid.has('plannedDate') ? 'Bắt buộc' : undefined}
              data-testid={`${TEST_ID}-field-plannedDate`}
            />
          </div>
          <div className={styles.field}>
            <Input
              label="Bắt đầu thực tế"
              type="datetime-local"
              value={toLocalInput(form.startedAt)}
              onChange={(e) => updateField('startedAt', fromLocalInput(e.target.value))}
              fullWidth
              data-testid={`${TEST_ID}-field-startedAt`}
            />
          </div>
        </div>
      </section>
      <section>
        <h3 className={styles.sectionTitle}>KPI / offline</h3>
        <div className={styles.fields} data-form-cols="5">
          <div className={fieldClass('checkInCount')}>
            <Input
              label="Số điểm check-in"
              required
              type="number"
              min={0}
              value={form.checkInCount}
              onChange={(e) =>
                updateField(
                  'checkInCount',
                  e.target.value === '' ? 0 : Number(e.target.value),
                )
              }
              fullWidth
              error={invalid.has('checkInCount') ? 'Bắt buộc ≥ 0' : undefined}
              data-testid={`${TEST_ID}-field-checkInCount`}
            />
          </div>
          <div className={fieldClass('coveragePercent')}>
            <Input
              label="Coverage %"
              type="number"
              min={0}
              max={100}
              step="0.1"
              value={form.coveragePercent}
              onChange={(e) =>
                updateField(
                  'coveragePercent',
                  e.target.value === '' ? 0 : Number(e.target.value),
                )
              }
              fullWidth
              error={invalid.has('coveragePercent') ? '0–100' : undefined}
              data-testid={`${TEST_ID}-field-coveragePercent`}
            />
          </div>
          <div className={fieldClass('offlineQueued')} data-testid={`${TEST_ID}-field-offlineQueued`}>
            <SearchInput
              label="Hàng đợi offline"
              config={OFFLINE_LOOKUP_CONFIG}
              value={form.offlineQueued ? 'true' : 'false'}
              primaryDisplay={form.offlineQueued ? 'Offline queue' : 'Online'}
              showSecondaryInput={false}
              onChange={(item) => updateField('offlineQueued', item.value === 'true')}
              onClear={() => updateField('offlineQueued', false)}
            />
          </div>
          <div className={`${styles.field} ${styles.span2}`}>
            <Input
              label="Ghi chú"
              value={form.note}
              onChange={(e) => updateField('note', e.target.value)}
              fullWidth
              data-testid={`${TEST_ID}-field-note`}
            />
          </div>
        </div>
      </section>
      <section data-zone="upload" data-testid={`${TEST_ID}-upload`}>
        <h3 className={styles.sectionTitle}>Ảnh / video hiện trường</h3>
        <div className={styles.mediaUpload}>
          <LinImageUpload
            purpose="patrol-session-media"
            product="rmms"
            entityType="patrol_session"
            entityId={currentId ?? undefined}
            items={mediaItems}
            onChange={onMediaChange}
            maxFiles={PATROL_MEDIA_MAX}
            maxBytes={PATROL_VIDEO_MAX_BYTES}
            accept={PATROL_MEDIA_ACCEPT}
            disabled={isView}
            confirmRemove={mode === 'edit'}
            labels={PATROL_MEDIA_LABELS}
            client={mediaApi}
            testId={`${TEST_ID}-field-mediaIds`}
          />
        </div>
      </section>
    </div>
  );

  useShellPageTitle(MODE_TITLE[mode]);
  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <LinPageHeader
        pageId={PAGE_ID}
        testIdPrefix={TEST_ID}
        title={MODE_TITLE[mode]}
        titleIconClass="fas fa-route"
        hint="Tuần đường / tuần kiểm"
      />
      {toolbar}
      {loading ? (
        <div className={styles.loading} data-testid={`${TEST_ID}-loading`}>
          Đang tải…
        </div>
      ) : (
        <>
          {showBanner ? (
            <div className={styles.banner} data-testid={`${TEST_ID}-banner`}>
              Vui lòng nhập đủ các trường bắt buộc (đánh dấu *).
            </div>
          ) : null}
          {isView ? viewBody : editBody}
        </>
      )}
      <GiaoViecModal
        open={giaoViecOpen}
        context={giaoViecContext}
        onClose={() => setGiaoViecOpen(false)}
        onCreated={(task, ctx) =>
          setChatTarget({
            taskId: task.id,
            from: ctx.source,
            sourceId: ctx.sourceEntityId,
            title: task.title,
          })
        }
      />
      <TaskChatPanel target={chatTarget} onClose={() => setChatTarget(null)} />
    </div>
  );
};

export default PatrolFormPage;
